#!/usr/bin/python3
"""Install the pinned S1 HelixScreen runtime and preserve KlipperScreen."""
import argparse
import hashlib
import ipaddress
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import tarfile

RELEASE_SHA = '361269dce1faa43e4acb5f06b1365490667b317d40f9a52e53e03586ecca29a3'
SOURCE = Path(__file__).resolve().parent


def put(path, data, mode=0o755):
    path.parent.mkdir(parents=True, exist_ok=True)
    pending = path.with_name(path.name + '.display-new')
    pending.write_bytes(data)
    pending.chmod(mode)
    os.replace(pending, path)


def configuration(template, ip, language):
    result = json.loads(json.dumps(template))
    result.update(wizard_completed=True, language=language, sounds_enabled=False,
                  ui_sounds_enabled=False, disable_sound=False, telemetry_enabled=False)
    result.setdefault('sound',{})['pwm_channel']='0:0'
    result['input']['touch_device'] = '/dev/input/event0'
    result['display'].update(rotate=180, animations_enabled=False, screensaver_type='off',
                             sleep_sec=0, dim_sec=0, time_format=1)
    printer = result['printers']['default']
    printer.update(wizard_completed=True, name='Kobra S1', moonraker_host=ip, moonraker_port=7125, moonraker_api_key=False)
    # KobraNest drives GPIO117 through Moonraker, not a Klipper LED output.
    leds=printer.setdefault('leds',{})
    leds.update(strip='',selected_strips=[])
    leds.setdefault('auto_state',{})['strips']=[]
    hardware=printer.setdefault('hardware',{})
    hardware['expected']=['heater_bed','extruder','controller_fan controller_fan',
                          'filament_switch_sensor filament_runout_nozzle',
                          'filament_switch_sensor filament_runout_rdm']
    widgets = [
        {'id':'printer_image','col':0,'row':0,'colspan':2,'rowspan':2,'enabled':True},
        {'id':'temp_graph','col':2,'row':0,'colspan':4,'rowspan':2,'enabled':True},
        {'id':'ams','col':0,'row':2,'colspan':4,'rowspan':1,'enabled':True},
        {'id':'power_device','col':0,'row':3,'colspan':1,'rowspan':1,'enabled':True,
         'config':{'device':'Bauraumlicht','icon':'lightbulb_on'}},
    ]
    for col, name in enumerate(('fan_stack','temperature','bed_temperature','filament','notifications'), 1):
        widgets.append({'id':name,'col':col,'row':3,'colspan':1,'rowspan':1,'enabled':True})
    # Explicitly disable unused defaults so migration does not insert widgets
    # into cells already occupied by the compact S1 layout.
    unused = ('print_status','tips','shutdown','lock','network','firmware_restart',
              'tool_switcher','led','led_controls','fan','nozzle_temps','chamber_temperature',
              'temp_stack','thermistor','preheat','bypass','active_spool','humidity',
              'width_sensor','favorite_macro','macros','motion','clock','control_buttons',
              'job_queue','clog_detection','print_stats','gcode_console','camera')
    for name in unused:
        widgets.append({'id':name,'col':-1,'row':-1,'colspan':1,'rowspan':1,'enabled':False})
    printer['panel_widgets'] = {'home':{'main_page_index':0,'next_page_id':1,
                                       'pages':[{'id':'main','widgets':widgets}]}}
    return result


ACEPRO_PANEL = ''

def install_acepro(root):
    """Install bundled ACE Pro panel; preserve other menus and back up changes."""
    import ast
    import base64
    import re
    import time
    import zlib
    panel = zlib.decompress(base64.b64decode(ACEPRO_PANEL))
    ast.parse(panel.decode('utf-8-sig'))
    ks = root/'opt/KlipperScreen'
    assert (ks/'screen.py').is_file(), 'KlipperScreen installation missing'
    menu = ks/'config/main_menu.conf'
    assert menu.is_file(), 'KlipperScreen main_menu.conf missing'
    text = menu.read_text(encoding='utf-8')
    for section in ('menu __main acepro', 'menu __print acepro'):
        replacement = '['+section+']\nname: ACE Pro\nicon: settings\npanel: acepro\n\n'
        # Section bodies end at the next section header, including comments.
        pattern = r'(?ms)^\['+re.escape(section)+r'\][ \t]*\r?\n.*?(?=^\[|\Z)'
        matches = list(re.finditer(pattern, text))
        if matches:
            first = True
            def replace(match):
                nonlocal first
                if first:
                    first = False
                    return replacement
                return ''
            text = re.sub(pattern, replace, text)
        else:
            text = text.rstrip()+'\n\n'+replacement
    changes = [(ks/'panels/acepro.py', panel), (menu, text.encode('utf-8'))]
    changed = [(p, data) for p, data in changes if not p.exists() or p.read_bytes() != data]
    if not changed:
        print('ACE Pro panel and menus already current')
        return
    backup = root/'var/backups/kobranest-acepro'/str(time.time_ns())
    backup.mkdir(parents=True)
    for path, data in changed:
        if path.exists():
            shutil.copy2(path, backup/path.name)
        put(path, data, 0o644)
    print('ACE Pro panel and both menus installed; backups:', backup)



LEGACY_RELEASE_SHAS = {'c6655f4fca7b004d26595a808db3da89e02207dc0c2aa6a87d384aa819235b66','6cb694d4b5935e027de5fa08598ea42445087b9dc13e4ad799064243e6556f32'}


def validate_runtime(root, destination):
    candidate_bin = destination/'bin/helix-screen'
    binary = candidate_bin if candidate_bin.is_file() else destination/'bin/helix-screen-fbdev'
    assert binary.is_file(), 'HelixScreen binary missing'
    command = ['/usr/bin/ldd', '/'+binary.relative_to(root).as_posix()]
    if root != Path('/'):
        command = [shutil.which('chroot') or '/usr/sbin/chroot', str(root)] + command
    result = subprocess.run(command, capture_output=True, text=True, check=True)
    assert 'not found' not in result.stdout+result.stderr, 'Runtime library missing'


def install_custom_images(destination):
    """Offer bundled artwork without changing the selected image or user files."""
    name = 'rinkhals_s1.png'
    source = SOURCE/'custom-images'/name
    data = source.read_bytes()
    assert hashlib.sha256(data).hexdigest() == '1a43fa4f9ac700bd4db64efe6539220e6a881ee4c3b21feeecf896db165256bf', 'Custom image checksum mismatch'
    target = destination/'config/custom_images'/name
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        print('Custom image already present; retained:', name)
    else:
        put(target, data, 0o644)
        print('Custom image available:', name)


def install_release(root, archive):
    """Upgrade only a recognized release, keeping settings and the previous tree."""
    import time
    destination = root/'opt/helixscreen'
    marker = destination/'.kobrian-release'
    if destination.exists():
        assert marker.is_file(), 'Unrecognized HelixScreen installation; not overwritten'
        version = marker.read_text().strip()
        assert version in LEGACY_RELEASE_SHAS | {RELEASE_SHA}, 'Unrecognized HelixScreen release; not overwritten'
        if version == RELEASE_SHA:
            return destination
    staging = root/'opt/helixscreen-install-pending'
    assert not staging.exists(), 'Previous partial install present; inspect before retry'
    staging.mkdir(parents=True)
    with tarfile.open(archive, 'r:gz') as tar:
        for item in tar:
            assert item.name == 'helixscreen' or item.name.startswith('helixscreen/')
            assert '..' not in Path(item.name).parts
        # Keep the SSH reader informed while the S1 expands the larger release.
        members = tar.getmembers()
        print('HelixScreen archive validated; extracting', len(members), 'entries', flush=True)
        def progress_members():
            for index, item in enumerate(members):
                if index % 50 == 0:
                    print('HelixScreen extraction:', index, '/', len(members), flush=True)
                yield item
        tar.extractall(staging, members=progress_members(), filter='data')
    candidate = staging/'helixscreen'
    assert (candidate/'config/settings.json.template').is_file(), 'Settings template missing'
    if destination.exists() and (destination/'config/settings.json').exists():
        settings = destination/'config/settings.json'
        json.loads(settings.read_text())
        shutil.copy2(settings, candidate/'config/settings.json')
    if (destination/'config/custom_images').is_dir():
        shutil.copytree(destination/'config/custom_images', candidate/'config/custom_images', dirs_exist_ok=True, symlinks=True)
    validate_runtime(root, candidate)
    put(candidate/'.kobrian-release', (RELEASE_SHA+'\n').encode(), 0o644)
    backup = None
    if destination.exists():
        backup = root/'var/backups/kobrian-display'/('helixscreen-'+str(time.time_ns()))
        backup.parent.mkdir(parents=True, exist_ok=True)
        os.replace(destination, backup)
    try:
        os.replace(candidate, destination)
    except OSError:
        if backup is not None:
            os.replace(backup, destination)
        raise
    staging.rmdir()
    print('HelixScreen release installed; previous tree:', backup or 'fresh install')
    return destination


def migrate_kobranest_settings(settings):
    """Repair legacy KobraNest defaults without assigning sensor roles or moving widgets."""
    saved=json.loads(settings.read_text());before=json.dumps(saved,sort_keys=True)
    active=saved.get('active_printer_id','default');profile=saved.get('printers',{}).get(active,{})
    if saved.get('wizard_completed') and profile:profile['wizard_completed']=True
    if saved.get('disable_sound'):
        saved.update(disable_sound=False,sounds_enabled=False,ui_sounds_enabled=False)
    saved.setdefault('sound',{})['pwm_channel']='0:0'
    hardware=profile.get('hardware',{});snapshot=hardware.get('last_snapshot',{})
    if isinstance(snapshot.get('leds'),list) and 'output_pin caselight' not in snapshot['leds']:
        def has_power(node):
            if isinstance(node,dict):return node.get('device')=='Bauraumlicht' or any(has_power(v) for v in node.values())
            if isinstance(node,list):return any(has_power(v) for v in node)
            return False
        if has_power(profile.get('panel_widgets',{})):
            leds=profile.get('leds',{})
            if leds.get('strip')=='output_pin caselight':leds['strip']=''
            for key in ('selected','selected_strips'):
                if isinstance(leds.get(key),list):leds[key]=[v for v in leds[key] if v!='output_pin caselight']
            auto=leds.get('auto_state',{})
            if isinstance(auto.get('strips'),list):auto['strips']=[v for v in auto['strips'] if v!='output_pin caselight']
    known=hardware.setdefault('expected',[])
    for name in ('controller_fan controller_fan','filament_switch_sensor filament_runout_nozzle','filament_switch_sensor filament_runout_rdm'):
        if name in snapshot.get('fans',[])+snapshot.get('filament_sensors',[]) and name not in known:known.append(name)
    if json.dumps(saved,sort_keys=True)!=before:
        backup=settings.with_name('settings.before-kobranest-usb-sound.json')
        if not backup.exists():shutil.copy2(settings,backup)
        put(settings,(json.dumps(saved,indent=2)+'\n').encode(),0o600)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', required=True)
    parser.add_argument('--pi-ip', required=True)
    parser.add_argument('--archive', type=Path)
    parser.add_argument('--language', choices=('de','en'), default='de')
    parser.add_argument('--default', choices=('helix','klipperscreen'))
    parser.add_argument('--start', action='store_true')
    args = parser.parse_args()
    root = Path(args.root).resolve()
    ip = str(ipaddress.IPv4Address(args.pi_ip))
    if args.start:
        assert root == Path('/') and 'busybox' in os.readlink('/proc/1/exe')
    assert (root/'etc/s1-boot-ready').is_file(), 'Kobrian root required'
    assert (root/'opt/KlipperScreen/screen.py').is_file(), 'Keep working KlipperScreen first'
    archive = args.archive or SOURCE/'helixscreen-kobranest-armhf.tar.gz'
    if not archive.exists():
        archive = SOURCE.parents[1]/'payload/helixscreen-kobranest-armhf.tar.gz'
    digest = hashlib.sha256()
    with archive.open('rb') as file:
        for block in iter(lambda:file.read(1048576), b''):
            digest.update(block)
    assert digest.hexdigest() == RELEASE_SHA, 'HelixScreen release checksum mismatch'
    destination = install_release(root, archive)
    settings = destination/'config/settings.json'
    if not settings.exists():
        template = json.loads((destination/'config/settings.json.template').read_text())
        put(settings, (json.dumps(configuration(template, ip, args.language), indent=2)+'\n').encode(), 0o600)
    else:
        saved=json.loads(settings.read_text())
        active=saved.get('active_printer_id','default')
        profile=saved.get('printers',{}).get(active,{})
        if saved.get('wizard_completed') and profile and not profile.get('wizard_completed'):
            profile['wizard_completed']=True
            backup=root/'var/backups/kobrian-display/settings-before-profile-completion.json'
            backup.parent.mkdir(parents=True,exist_ok=True)
            if not backup.exists():shutil.copy2(settings,backup)
            put(settings,(json.dumps(saved,indent=2)+'\n').encode(),0o600)

    migrate_kobranest_settings(settings)
    install_custom_images(destination)
    validate_runtime(root, destination)
    service = root/'usr/local/sbin/s1-service'
    text = service.read_text()
    previous = 'exec /usr/local/sbin/s1-gui >>/var/log/s1-gui.log 2>&1'
    replacement = 'exec /usr/local/sbin/s1-ui >>/var/log/s1-gui.log 2>&1'
    assert previous in text or replacement in text, 'Unknown GUI dispatcher'
    backup = root/'var/backups/kobrian-display'
    backup.mkdir(parents=True, exist_ok=True)
    if not (backup/'s1-service').exists():
        shutil.copy2(service, backup/'s1-service')
    for name in ('s1-ui','s1-ui-select','s1-helix'):
        put(root/'usr/local/sbin'/name, (SOURCE/name).read_bytes())
    put(service, text.replace(previous, replacement).encode())
    selection = root/'etc/s1-ui'
    target = args.default or (selection.read_text().strip() if selection.exists() else 'helix')
    assert target in ('helix','klipperscreen')
    put(selection, (target+'\n').encode(), 0o644)
    install_acepro(root)
    os.sync()
    if args.start:
        # Only the init-owned GUI supervisor is stopped. MCU services are untouched.
        candidates = []
        for proc in Path('/proc').iterdir():
            if not proc.name.isdigit():
                continue
            try:
                argv = (proc/'cmdline').read_bytes().split(b'\0')
                parent = next(line for line in (proc/'status').read_text().splitlines() if line.startswith('PPid:')).split()[1]
            except (OSError, StopIteration):
                continue
            if parent == '1' and any(arg in (b'/usr/local/sbin/s1-gui', b'/usr/local/sbin/s1-helix', b'/usr/local/sbin/s1-ui') for arg in argv):
                candidates.append(int(proc.name))
        assert len(candidates) == 1, 'Expected exactly one init GUI supervisor'
        os.kill(candidates[0], signal.SIGTERM)
    print('HelixScreen installed; KlipperScreen preserved; default:', target)


if __name__ == '__main__':
    main()
